sys_script_fix.script:
(function executeRule(current, previous /*null when async*/ ) {

    var parent_record = new GlideRecord('dmn_demand');
    if (parent_record.get('a31a69ba47597150020ba9f8536d43ed')) {
        var survey_response = new GlideRecord('asmt_metric_result');
        survey_response.addQuery('instance', '5ddb5b3f4799f550020ba9f8536d43d2');
        survey_response.query();
        var notes = '';
        while (survey_response.next()) {
           var workNotes;

           //workNotes += '<strong>Ideation Assessment Questions</strong>'

            workNotes += '<style> table, th, td {border: 1px solid black;border-collapse: collapse;background-color:lightyellow;padding:2px;text-align: left;}</style><table style="width:100%">';

        // Assuming assessment responses are stored in the "Question" field
        workNotes += '<tr style="height: 50.4px;"><td style="width: 700px; height: 15.4px;"><strong>' + survey_response.instance_question.getDisplayValue() +'</strong></td>' + '<td style="text-align: center;">' + survey_response.string_value + '</td>';

        // End the table
        workNotes += '</table>';

        }

        parent_record.work_notes ='[code]' +  workNotes + '[/code]';
        parent_record.update();
    }



})(current, previous);
